def match_aws(text: str):
    return [p for p in PATTERNS if p.platform=="aws" and p.compiled.search(text)]

def match_github(text: str):
    return [p for p in PATTERNS if p.platform=="github" and p.compiled.search(text)]

def match_generic(text: str):
    return [p for p in PATTERNS if p.compiled.search(text)]

def get_pattern(pid: str) -> Optional[Pattern]:
    for p in PATTERNS:
        if p.id==pid:
            return p
    return None

def severity_rank(sev: str) -> int:
    return {"low":1,"medium":2,"high":3,"critical":4}.get(sev,2)
